queries.HealthSummary:
query HealthSummary(
$path: [HierarchyNodeInput],
$start: DateTime,
$end: DateTime,
$granularity: String,
$filter: FilterInput
) {
  network(start: $start, end: $end, filter: $filter) {
    timeSeries(
      path: $path,
      start: $start,
      end: $end,
      granularity: $granularity
    ) { connectionSuccessAndAttemptCount }
    avgTTC: hierarchyNode(path: $path) {
      incidentCharts: timeSeries(granularity: $granularity) {
        ttc: timeToConnect
      }
    }
  }
}

queries.NetworkHistoryWidget:
query NetworkHistoryWidget(
$path:[HierarchyNodeInput],
$start: DateTime,
$end: DateTime,
$granularity: String,
$severity: [Range],
$code: [String],
$filter: FilterInput
){
network(start: $start end: $end, filter : $filter){
    hierarchyNode(path:$path){
    timeSeries(granularity:$granularity){
        time
        newClientCount: connectionAttemptCount
        impactedClientCount: impactedClientCountBySeverity(
            filter:{severity:$severity, code: $code}
        )
        connectedClientCount
    }
    }
}
}

queries.ConnectionDrilldown:
query ConnectionDrilldown(
  $path: [HierarchyNodeInput]
  $start: DateTime
  $end: DateTime
  $granularity: String
  $filter: FilterInput
) {
  network(start: $start, end: $end, filter: $filter) {
    connectionDrilldown: timeSeries(
      path: $path
      start: $start
      end: $end
      granularity: $granularity
    ) {
      assocSuccessAndAttemptCount
      authSuccessAndAttemptCount
      eapSuccessAndAttemptCount
      radiusSuccessAndAttemptCount
      dhcpSuccessAndAttemptCount
    }
  }
}

queries.timeseriesKPI:
query timeseriesKPI(
  $start: DateTime
  $end: DateTime
  $granularity: String
  $filter: FilterInput
  ) {
  network(filter: $filter) {
    timeSeries: timeSeries(
      start: $start
      end: $end
      granularity: $granularity
      ) {
      time
      data: connectionSuccessAndAttemptCount
    }
  }
}
